from decimal import Decimal, ROUND_FLOOR, ROUND_CEILING, getcontext
import json, sys, datetime
sys.set_int_max_str_digits(0)
getcontext().prec = 80
R = Path('certification/results')

def bnd(s, up, digits=16):
    """Directional decimal rounding of a stored bound string (arb ball '[mid +/- rad]' or plain decimal)."""
    s = str(s).strip().strip('[]'); mid, _, rad = s.partition(' +/- '); m = Decimal(mid.strip()); r = Decimal(rad.strip() or '0')
    v = m + r if up else m - r
    if v == 0: return '0'
    q = Decimal(1).scaleb(v.adjusted() - digits + 1)
    return f'{v.quantize(q, rounding=ROUND_CEILING if up else ROUND_FLOOR):.{digits-1}e}'
def lo(s, d=16): return bnd(s, False, d)
def up(s, d=16): return bnd(s, True, d)
def J(name):
    p = R / name
    return json.loads(p.read_text()) if p.exists() else None

